Hier ein Beispielcodeausschnitt, der das Zeichnen des Spielfelds mit SDL2 demonstriert:

```c
#include <SDL2/SDL.h>

// Struktur für die Schlangenart
typedef struct {
    SDL_Point *body;  // Array mit Koordinaten für die Schlangenart
    int length;      // Anzahl der Schlangenteile
    SDL_Point head;   // Koordinate des Schlangenkopfes
    int direction;   // Richtung der Schlangenart (0 = oben, 1 = rechts, 2 = unten, 3 = links)
} Snake;

// Funktion zum Zeichnen des Spielfelds
void renderField(SDL_Renderer *renderer, Snake *snake, SDL_Point fruit) {
    // Spielfeld zeichnen
    SDL_SetRenderDrawColor(renderer, 255, 255, 255, SDL_ALPHA_OPAQUE); // Weiß
    SDL_RenderFillRect(renderer, NULL);

    // Schlangenart zeichnen
    SDL_SetRenderDrawColor(renderer, 0, 128, 0, SDL_ALPHA_OPAQUE); // Grün
    for (int I = 0; I < snake->length; i++) {
        SDL_Point current = snake->body[i];
        SDL_RenderFillRect(renderer, (SDL_Rect*) &current);
    }

    // Frucht zeichnen
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, SDL_ALPHA_OPAQUE); // Rot
    SDL_RenderFillRect(renderer, (SDL_Rect*) &fruit);

    // Schlangenkopf zeichnen
    SDL_SetRenderDrawColor(renderer, 0, 0, 255, SDL_ALPHA_OPAQUE); // Blau
    SDL_RenderFillRect(renderer, (SDL_Rect*) &snake->head);
}

int main(int argc, char *argv[]) {
    // SDL2 Initialisierung
    SDL_Init(SDL_INIT_VIDEO);

    // Fenster erstellen
    SDL_Window *window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        640, 640,
        SDL_WINDOW_SHOWN
    );

    // Renderer erstellen
    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Spiellogik und Variablen initialisieren
    Snake snake = {0};
    snake.body = malloc(sizeof(SDL_Point) * 3);  // Anfangslänge der Schlangenart
    snake.body[0].x = 320 - 20;
    snake.body[0].y = 320 - 20;
    snake.body[1].x = 320;
    snake.body[1].y = 320 - 20;
    snake.body[2].x = 320 + 20;
    snake.body[2].y = 320 - 20;
    snake.length = 3;
    snake.head = snake.body[0];
    snake.direction = 0;  // Anfangsrichtung nach oben

    SDL_Point fruit = {rand() % 640 / 20 * 20, rand() % 640 / 20 * 20};

    bool running = true;

    while (running) {
        // Eingaben empfangen und Schlangenart steuern
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        if (snake.direction != 1) {
                            snake.direction = 0;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake.direction != 0) {
                            snake.direction = 1;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake.direction != 3) {
                            snake.direction = 2;
                        }
                        break;
                    case SDLK_LEFT:
                        if (snake.direction != 2) {
                            snake.direction = 3;
                        }
                        break;
                    case SDLK_ESCAPE:
                        running = false;
                        break;
                }
            }
        }

        // Schlangenart bewegen und Frucht generieren
        // ...

        // Spielfeld rendern
        SDL_RenderClear(renderer);
        renderField(renderer, &snake, fruit);
        SDL_RenderPresent(renderer);
    }

    // SDL2 Beenden
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

Dieser Codeausschnitt demonstriert lediglich das Zeichnen des Spielfelds mit SDL2 und ist noch nicht vollständig. Sie sollten Ihre Spiellogik, Eingaben und weiteren Teile hinzufügen, um ein vollständiges Schlangenspiel zu erstellen.

